/* Jolly Zebra 42 by Gumpack — https://uiverse.io/Gumpack/jolly-zebra-42 */
.btn {
 background-image: linear-gradient(45deg, #FF512F 0%, #F09819  51%, #FF512F  100%)
}

.btn {
 margin: 10px;
 padding: 15px 30px;
 text-align: center;
 text-transform: uppercase;
 transition: 0.5s;
 background-size: 200% auto;
 color: white;
 border-radius: 10px;
 display: block;
 border: 0px;
 font-weight: 700;
 box-shadow: 0px 0px 14px -7px #f09819;
}

.btn:hover {
 background-position: right center;

 color: #fff;
 text-decoration: none;
}

.btn:active {
 transform: scale(0.95);
}
